// Merge the Cindy locale subsets (generated by build/sync-cindy.mjs) into
// WinOne's single translation store. WinOne keys win when both define one.
import {i18n} from '../../../i18n';
import schedulerEn from '../locales/scheduler.en.json';
import schedulerZh from '../locales/scheduler.zh-CN.json';

i18n.addResourceBundle('en-US', 'translation', schedulerEn, true, false);
i18n.addResourceBundle('zh-CN', 'translation', schedulerZh, true, false);
